1	import { component$, useStore, useVisibleTask$ } from "@qwik.dev/core";
2	import { useSpeechPlayer } from "../../utils/use-speech-player";
3	import { openLiveVoice } from "../../utils/live-voice-workspace";
4	import {
5	  currentSpeechSourceOffset,
6	  currentSpeechText,
7	  resumeSpeech,
8	  seekSpeech,
9	  speechState,
10	} from "../../utils/speech";
11	import {
12	  buildSpeechTimeline,
13	  type SpeechTimeline,
14	} from "../../utils/speech-follow-along";
15	import { alignmentRangeAtTime } from "../../utils/speech-alignment";
16	import {
17	  buildSpeechSourceMap,
18	  mapSpeechSourceRange,
19	  type SpeechSourceMap,
