22	const SENTENCE_HIGHLIGHT = "twyne-speech-sentence";
23	const WORD_HIGHLIGHT = "twyne-speech-word";
24	
25	interface SpeechTextSlice {
26	  node: Text;
27	  start: number;
28	  end: number;
29	}
30	
31	interface SpeechTextMap {
32	  root: HTMLElement;
33	  text: string;
34	  slices: SpeechTextSlice[];
35	  timeline: SpeechTimeline;
36	  sourceMap: SpeechSourceMap | null;
37	  sourceText: string | null;
38	  sourceOffset: number | null;
39	  /** Location of the exact clip text inside the rendered target. */
40	  spokenStart: number;
41	  spokenEnd: number;
42	}
43	
44	interface HighlightRegistryLike {
45	  set(name: string, highlight: unknown): void;
46	  delete(name: string): void;
47	}
48	
49	type HighlightConstructor = new (...ranges: Range[]) => unknown;
50	
51	function speechHighlightApi(): {
52	  registry: HighlightRegistryLike;
53	  Highlight: HighlightConstructor;
54	} | null {
55	  const registry = (CSS as unknown as { highlights?: HighlightRegistryLike })
56	    .highlights;
57	  const Highlight = (window as unknown as { Highlight?: HighlightConstructor })
58	    .Highlight;
59	  return registry && Highlight ? { registry, Highlight } : null;
60	}
61	
62	function clearSpeechHighlights(): void {
63	  const api = speechHighlightApi();
64	  api?.registry.delete(WORD_HIGHLIGHT);
65	  api?.registry.delete(SENTENCE_HIGHLIGHT);
66	}
