68	function buildSpeechTextMap(root: HTMLElement): SpeechTextMap {
69	  const slices: SpeechTextSlice[] = [];
70	  const parts: string[] = [];
71	  let length = 0;
72	  let previousBlock: Element | null = null;
73	  const blockTags = new Set([
74	    "ADDRESS",
75	    "ARTICLE",
76	    "ASIDE",
77	    "BLOCKQUOTE",
78	    "DIV",
79	    "FIGCAPTION",
80	    "H1",
81	    "H2",
82	    "H3",
83	    "H4",
84	    "H5",
85	    "H6",
86	    "LI",
87	    "P",
88	    "PRE",
89	    "SECTION",
90	  ]);
91	  const nearestBlock = (textNode: Text): Element => {
92	    let element: Element | null = textNode.parentElement;
93	    while (element && element !== root) {
94	      if (blockTags.has(element.tagName)) return element;
95	      element = element.parentElement;
96	    }
97	    return root;
98	  };
99	  const walker = document.createTreeWalker(
100	    root,
101	    NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT,
102	    {
103	      acceptNode(node) {
104	        const parent = node.parentElement;
105	        if (
106	          !parent ||
107	          parent.closest(
108	            'button, input, select, textarea, script, style, [aria-hidden="true"], [data-speech-ignore]',
109	          )
110	        ) {
111	          return NodeFilter.FILTER_REJECT;
112	        }
113	        if (node instanceof Element)
114	          return node.tagName === "BR"
115	            ? NodeFilter.FILTER_ACCEPT
116	            : NodeFilter.FILTER_SKIP;
117	        if (
118	          !(node as Text).data.trim() &&
119	          ((parent === root && root.children.length) ||
120	            ["UL", "OL", "TABLE", "THEAD", "TBODY", "TR"].includes(
121	              parent.tagName,
122	            ))
123	        ) {
124	          return NodeFilter.FILTER_REJECT;
125	        }
126	        return node.textContent?.length
127	          ? NodeFilter.FILTER_ACCEPT
128	          : NodeFilter.FILTER_REJECT;
129	      },
130	    },
131	  );
132	
133	  let node = walker.nextNode();
134	  while (node) {
135	    if (node instanceof Element) {
136	      parts.push("\n");
137	      length += 1;
138	      node = walker.nextNode();
139	      continue;
140	    }
141	    const textNode = node as Text;
142	    const value = textNode.data;
143	    const block = nearestBlock(textNode);
144	    if (
145	      previousBlock &&
146	      block !== previousBlock &&
147	      !block.contains(previousBlock) &&
148	      !previousBlock.contains(block)
149	    ) {
150	      parts.push("\n\n");
151	      length += 2;
152	    }
153	    slices.push({ node: textNode, start: length, end: length + value.length });
154	    parts.push(value);
155	    length += value.length;
156	    previousBlock = block;
157	    node = walker.nextNode();
158	  }
159	
160	  const text = parts.join("");
161	  const sourceText = currentSpeechText();
162	  const sourceOffset = currentSpeechSourceOffset();
163	  const sourceMap = sourceText
164	    ? buildSpeechSourceMap(sourceText, text, {
165	        sourceOffset:
166	          root.dataset.speechSource === "plain" ? sourceOffset : null,
167	        markdown: root.dataset.speechSource !== "plain",
168	      })
169	    : null;
170	  const spokenStart = sourceMap?.renderedStart ?? 0;
171	  const spokenEnd = sourceMap?.renderedEnd ?? text.length;
172	  const timeline = buildSpeechTimeline(text);
173	  return {
174	    root,
175	    text,
176	    slices,
177	    timeline,
178	    sourceMap,
179	    sourceText,
180	    sourceOffset,
181	    spokenStart,
182	    spokenEnd,
183	  };
184	}
185	
186	function textRange(
187	  map: SpeechTextMap,
188	  start: number,
189	  end: number,
190	): Range | null {
191	  if (!map.slices.length || end <= start) return null;
192	  const startSlice =
193	    map.slices.find((slice) => start >= slice.start && start < slice.end) ??
194	    map.slices[0];
195	  const endSlice =
196	    map.slices.find((slice) => end >= slice.start && end <= slice.end) ??
197	    map.slices[map.slices.length - 1];
198	  const range = document.createRange();
199	  range.setStart(
200	    startSlice.node,
201	    Math.max(0, Math.min(start - startSlice.start, startSlice.node.length)),
202	  );
203	  range.setEnd(
204	    endSlice.node,
205	    Math.max(0, Math.min(end - endSlice.start, endSlice.node.length)),
206	  );
207	  return range;
208	}
209	
210	function caretOffsetFromPoint(
211	  map: SpeechTextMap,
212	  x: number,
213	  y: number,
214	): number | null {
215	  const documentWithCaret = document as Document & {
216	    caretPositionFromPoint?: (
217	      clientX: number,
218	      clientY: number,
219	    ) => { offsetNode: Node; offset: number } | null;
220	    caretRangeFromPoint?: (clientX: number, clientY: number) => Range | null;
221	  };
222	  const position = documentWithCaret.caretPositionFromPoint?.(x, y);
223	  const fallback = position
224	    ? null
225	    : documentWithCaret.caretRangeFromPoint?.(x, y);
226	  const node = position?.offsetNode ?? fallback?.startContainer;
227	  const offset = position?.offset ?? fallback?.startOffset;
228	  if (
229	    !(node instanceof Text) ||
230	    offset === undefined ||
231	    !map.root.contains(node)
232	  ) {
233	    return null;
234	  }
235	  const slice = map.slices.find((candidate) => candidate.node === node);
236	  return slice ? slice.start + offset : null;
237	}
