239	function findSpeechTarget(id: string): HTMLElement | null {
240	  const candidates = document.querySelectorAll<HTMLElement>(
241	    `[data-speech-id="${CSS.escape(id)}"]`,
242	  );
243	  return (
244	    Array.from(candidates).find(
245	      (candidate) => candidate.getClientRects().length > 0,
246	    ) ?? null
247	  );
248	}
