250	/**
251	 * The face of whoever is reading `root` aloud: the nearest portrait in the
252	 * card around it, matched by speaker name when one is known so a neighbour's
253	 * face never mouths someone else's note.
254	 */
255	function findSpeakingPortrait(
256	  root: HTMLElement,
257	  speaker: string | null,
258	): HTMLElement | null {
259	  let scope: HTMLElement | null = root;
260	  for (let depth = 0; scope && depth < 6; depth++) {
261	    const portraits = Array.from(
262	      scope.querySelectorAll<HTMLElement>(
263	        ".persona-portrait:not([data-speaking='live'])",
264	      ),
265	    );
266	    const match = speaker
267	      ? portraits.find((p) => p.dataset.personaName === speaker)
268	      : portraits[0];
269	    if (match) return match;
270	    if (portraits.length) return null;
271	    scope = scope.parentElement;
272	  }
273	  return null;
274	}
