276	function scrollRangeIntoView(range: Range, root: HTMLElement): void {
277	  const rect = range.getBoundingClientRect();
278	  if (!rect.height) return;
279	
280	  let scrollParent: HTMLElement | null = root.parentElement;
281	  while (scrollParent) {
282	    const style = window.getComputedStyle(scrollParent);
283	    if (
284	      /(auto|scroll)/u.test(style.overflowY) &&
285	      scrollParent.scrollHeight > scrollParent.clientHeight
286	    ) {
287	      break;
288	    }
289	    scrollParent = scrollParent.parentElement;
290	  }
291	
292	  const bounds = scrollParent?.getBoundingClientRect();
293	  const top = bounds?.top ?? 0;
294	  const bottom = bounds?.bottom ?? window.innerHeight;
295	  if (rect.top >= top + 48 && rect.bottom <= bottom - 72) return;
296	
297	  const behavior = window.matchMedia("(prefers-reduced-motion: reduce)").matches
298	    ? "auto"
299	    : "smooth";
300	  const delta = rect.top - (top + (bottom - top) * 0.42);
301	  if (scrollParent) scrollParent.scrollBy({ top: delta, behavior });
302	  else window.scrollBy({ top: delta, behavior });
303	}
