305	function formatClock(seconds: number): string {
306	  if (!Number.isFinite(seconds) || seconds <= 0) return "0:00";
307	  const whole = Math.floor(seconds);
308	  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}`;
309	}
