311	/** Persistent transport for every narration surface in the application. */
312	export const GlobalSpeechPlayer = component$(() => {
313	  const player = useSpeechPlayer();
314	  const local = useStore({ customVoice: "", customOpen: false });
315	
316	  // Use native provider timing when it exists. Providers without alignment
317	  // get one honest clip-level highlight; elapsed duration is never converted
318	  // into manufactured word timing. The Highlight API preserves Markdown DOM.
319	  // eslint-disable-next-line qwik/no-use-visible-task
320	  useVisibleTask$(
321	    ({ cleanup }) => {
322	      let activeMap: SpeechTextMap | null = null;
323	      let activeId = "";
324	      let activeMapDirty = false;
325	      let textObserver: MutationObserver | null = null;
326	      let lastSentence = "";
327	      let pointerId: number | null = null;
328	      let pointerType = "";
329	      let pointerStart = { x: 0, y: 0 };
330	      let resumeAfterSeek = false;
331	      let didSeek = false;
332	      let talkingFace: HTMLElement | null = null;
333	
334	      const setTalkingFace = (face: HTMLElement | null) => {
335	        if (face === talkingFace) return;
336	        if (talkingFace?.dataset.speaking === "tts")
337	          delete talkingFace.dataset.speaking;
338	        talkingFace = face;
339	        if (face) face.dataset.speaking = "tts";
340	      };
341	
342	      const clearActive = () => {
343	        setTalkingFace(null);
344	        textObserver?.disconnect();
345	        textObserver = null;
346	        if (activeMap) {
347	          delete activeMap.root.dataset.speechActive;
348	          activeMap.root.classList.remove("is-speech-seeking");
349	        }
350	        activeMap = null;
351	        activeId = "";
352	        activeMapDirty = false;
353	        lastSentence = "";
354	        clearSpeechHighlights();
355	      };
356	
357	      const sync = () => {
358	        const snapshot = speechState();
359	        if (
360	          !snapshot.id ||
361	          snapshot.status === "idle" ||
362	          snapshot.status === "error"
363	        ) {
364	          clearActive();
365	          return;
366	        }
367	
368	        if (
369	          snapshot.id !== activeId ||
370	          !activeMap?.root.isConnected ||
371	          activeMap.sourceText !== currentSpeechText() ||
372	          activeMap.sourceOffset !== currentSpeechSourceOffset() ||
373	          activeMapDirty
374	        ) {
375	          clearActive();
376	          const root = findSpeechTarget(snapshot.id);
377	          if (!root) return;
378	          activeMap = buildSpeechTextMap(root);
379	          activeId = snapshot.id;
380	          textObserver = new MutationObserver(() => {
381	            activeMapDirty = true;
382	          });
383	          textObserver.observe(root, {
384	            childList: true,
385	            characterData: true,
386	            subtree: true,
387	          });
388	          root.dataset.speechActive = snapshot.status;
389	        } else {
390	          activeMap.root.dataset.speechActive = snapshot.status;
391	        }
392	        setTalkingFace(
393	          snapshot.status === "playing"
394	            ? findSpeakingPortrait(activeMap.root, snapshot.label)
395	            : null,
396	        );
397	
398	        if (!activeMap) {
399	          clearSpeechHighlights();
400	          return;
401	        }
402	        const api = speechHighlightApi();
403	        if (!api) return;
404	        clearSpeechHighlights();
405	
406	        const native = alignmentRangeAtTime(
407	          snapshot.alignment,
408	          snapshot.currentTime,
409	        );
410	        const mapped = native
411	          ? mapSpeechSourceRange(
412	              activeMap.sourceMap,
413	              native.sourceStart,
414	              native.sourceEnd,
415	            )
416	          : null;
417	        const nativeStart = mapped?.start ?? null;
418	        const nativeEnd = mapped?.end ?? null;
419	        const timelineWord =
420	          nativeStart === null
421	            ? null
422	            : (activeMap.timeline.words.find(
423	                (word) =>
424	                  nativeStart >= word.start && nativeStart < word.sentenceEnd,
425	              ) ?? null);
426	        const sentenceStart = timelineWord
427	          ? Math.max(timelineWord.sentenceStart, activeMap.spokenStart)
428	          : activeMap.spokenStart;
429	        const sentenceEnd = timelineWord
430	          ? Math.min(timelineWord.sentenceEnd, activeMap.spokenEnd)
431	          : activeMap.spokenEnd;
432	        const sentence = textRange(activeMap, sentenceStart, sentenceEnd);
433	        const word =
434	          native?.precision === "word" &&
435	          nativeStart !== null &&
436	          nativeEnd !== null
437	            ? textRange(activeMap, nativeStart, nativeEnd)
438	            : null;
439	        if (sentence) {
440	          api.registry.set(SENTENCE_HIGHLIGHT, new api.Highlight(sentence));
441	        }
442	        if (word) api.registry.set(WORD_HIGHLIGHT, new api.Highlight(word));
443	
444	        const sentenceKey = `${activeId}:${sentenceStart}`;
445	        if (sentence && sentenceKey !== lastSentence && pointerId === null) {
446	          lastSentence = sentenceKey;
447	          scrollRangeIntoView(sentence, activeMap.root);
448	        }
449	      };
450	
451	      const seekFromPoint = (x: number, y: number) => {
452	        const snapshot = speechState();
453	        if (
454	          !activeMap ||
455	          snapshot.id !== activeId ||
456	          snapshot.duration <= 0 ||
457	          (snapshot.status !== "playing" && snapshot.status !== "paused")
458	        ) {
459	          return;
460	        }
461	        const offset = caretOffsetFromPoint(activeMap, x, y);
462	        if (offset === null) return;
463	        const native = snapshot.alignment.find((range) => {
464	          const mapped = mapSpeechSourceRange(
465	            activeMap!.sourceMap,
466	            range.sourceStart,
467	            range.sourceEnd,
468	          );
469	          return mapped && offset >= mapped.start && offset < mapped.end;
470	        });
471	        if (!native) return;
472	        seekSpeech(native.audioStart);
473	        didSeek = true;
474	      };
475	
476	      const onPointerDown = (event: PointerEvent) => {
477	        if (event.button !== 0 || pointerId !== null || !activeMap) return;
478	        const target = event.target instanceof Element ? event.target : null;
479	        const root = target?.closest<HTMLElement>("[data-speech-id]");
480	        if (
481	          root !== activeMap.root ||
482	          target?.closest("a, button, input, select, textarea")
483	        ) {
484	          return;
485	        }
486	        const snapshot = speechState();
487	        if (
488	          snapshot.id !== activeId ||
489	          snapshot.duration <= 0 ||
490	          snapshot.alignment.length === 0 ||
491	          (snapshot.status !== "playing" && snapshot.status !== "paused")
492	        ) {
493	          return;
494	        }
495	
496	        pointerId = event.pointerId;
497	        pointerType = event.pointerType;
498	        pointerStart = { x: event.clientX, y: event.clientY };
499	        resumeAfterSeek = snapshot.status === "paused";
500	        didSeek = false;
501	        activeMap.root.classList.add("is-speech-seeking");
502	        if (pointerType !== "touch") {
503	          event.preventDefault();
504	          activeMap.root.setPointerCapture?.(event.pointerId);
505	          seekFromPoint(event.clientX, event.clientY);
506	        }
507	      };
508	
509	      const onPointerMove = (event: PointerEvent) => {
510	        if (event.pointerId !== pointerId || pointerType === "touch") return;
511	        event.preventDefault();
512	        seekFromPoint(event.clientX, event.clientY);
513	      };
514	
515	      const finishPointer = (event: PointerEvent, cancelled = false) => {
516	        if (event.pointerId !== pointerId) return;
517	        if (
518	          !cancelled &&
519	          pointerType === "touch" &&
520	          Math.hypot(
521	            event.clientX - pointerStart.x,
522	            event.clientY - pointerStart.y,
523	          ) < 8
524	        ) {
525	          seekFromPoint(event.clientX, event.clientY);
526	        }
527	        activeMap?.root.classList.remove("is-speech-seeking");
528	        if (resumeAfterSeek && didSeek) resumeSpeech();
529	        pointerId = null;
530	        pointerType = "";
531	        resumeAfterSeek = false;
532	        didSeek = false;
533	        sync();
534	      };
535	      const onPointerCancel = (event: PointerEvent) =>
536	        finishPointer(event, true);
537	
538	      window.addEventListener("twyne:speech", sync);
539	      document.addEventListener("pointerdown", onPointerDown);
540	      document.addEventListener("pointermove", onPointerMove);
541	      document.addEventListener("pointerup", finishPointer);
542	      document.addEventListener("pointercancel", onPointerCancel);
543	      sync();
544	
545	      cleanup(() => {
546	        clearActive();
547	        window.removeEventListener("twyne:speech", sync);
548	        document.removeEventListener("pointerdown", onPointerDown);
549	        document.removeEventListener("pointermove", onPointerMove);
550	        document.removeEventListener("pointerup", finishPointer);
551	        document.removeEventListener("pointercancel", onPointerCancel);
552	      });
553	    },
554	    { strategy: "document-ready" },
555	  );
556	
557	  if (player.state.status === "idle") return null;
558	
559	  const busy = player.state.status === "loading";
560	  const paused = player.state.status === "paused";
561	  const playing = player.state.status === "playing";
562	  const canGoBack = player.state.queueIndex > 0 || player.state.currentTime > 0;
563	  const canGoNext = player.state.queueIndex < player.state.queueLength - 1;
564	  const progressMax = Math.max(player.state.duration, 0);
565	
566	  return (
567	    <aside
568	      class="fixed bottom-3 left-1/2 w-[min(44rem,calc(100vw-1rem))] -translate-x-1/2 border border-[var(--color-paper-3)] bg-[var(--color-paper)]"
569	      style={{
570	        zIndex: "var(--z-overlay)",
571	        borderRadius: "4px",
572	        boxShadow:
573	          "0 4px 8px color-mix(in srgb, var(--shade) 24%, transparent)",
574	      }}
575	      aria-label="Global narration player"
576	    >
577	      <div class="flex min-w-0 flex-wrap items-center gap-2 px-2.5 py-2 sm:gap-3 sm:px-3">
578	        <div class="min-w-0 flex-1">
579	          <div class="flex min-w-0 items-baseline gap-2">
580	            <p
581	              class="truncate text-xs font-semibold text-[var(--color-ink)]"
582	              style={{ fontFamily: "var(--font-display)" }}
583	            >
584	              {player.state.label || "Read aloud"}
585	            </p>
586	            {player.state.queueLength > 1 && (
587	              <span
588	                class="shrink-0 text-[0.6rem] text-[var(--color-ink-muted)]"
589	                style={{ fontFamily: "var(--font-typewriter)" }}
590	              >
591	                {player.state.queueIndex + 1} of {player.state.queueLength}
592	              </span>
593	            )}
594	          </div>
595	          <p
596	            class="truncate text-[0.6rem] text-[var(--color-ink-muted)]"
597	            style={{ fontFamily: "var(--font-typewriter)" }}
598	          >
599	            {player.state.status === "error"
600	              ? player.state.error?.message || "Narration failed"
601	              : busy
602	                ? "Preparing voice…"
603	                : `${player.voiceMenu.provider || player.state.provider || "Voice"} · ${player.voiceMenu.model || player.state.model || "narration"}`}
604	          </p>
605	          {player.state.status === "error" &&
606	            player.state.error?.referenceId && (
607	              <p class="break-all text-[0.6rem] text-[var(--color-ink-muted)]">
608	                Reference: {player.state.error.referenceId}
609	              </p>
610	            )}
611	        </div>
612	
613	        <div class="flex shrink-0 items-center gap-1">
614	          <button
615	            type="button"
616	            class="tool-btn"
617	            title="Talk with this editor"
618	            aria-label="Talk with this editor"
619	            onClick$={() =>
620	              openLiveVoice(
621	                player.state.label ?? undefined,
622	                currentSpeechText() ?? undefined,
623	              )
624	            }
625	          >
626	            ◉ <span class="hidden sm:inline">Talk</span>
627	          </button>
628	          <button
629	            type="button"
630	            class="tool-btn"
631	            aria-label="Previous passage"
632	            title="Previous passage"
633	            disabled={!canGoBack || busy}
634	            onClick$={player.previous$}
635	          >
636	            ↶
637	          </button>
638	          <button
639	            type="button"
640	            class="btn-press flex h-8 w-8 items-center justify-center p-0 disabled:opacity-50"
641	            aria-label={
642	              player.state.status === "error"
643	                ? "Retry narration"
644	                : playing
645	                  ? "Pause narration"
646	                  : "Resume narration"
647	            }
648	            title={
649	              player.state.status === "error"
650	                ? "Retry narration"
651	                : playing
652	                  ? "Pause narration"
653	                  : "Resume narration"
654	            }
655	            disabled={busy}
656	            onClick$={
657	              player.state.status === "error" ? player.retry$ : player.toggle$
658	            }
659	          >
660	            {busy ? "…" : playing ? "Ⅱ" : paused ? "▶" : "!"}
661	          </button>
662	          <button
663	            type="button"
664	            class="tool-btn"
665	            aria-label="Next passage"
666	            title="Next passage"
667	            disabled={!canGoNext || busy}
