68	function buildSpeechTextMap(root: HTMLElement): SpeechTextMap {
69	  const slices: SpeechTextSlice[] = [];
70	  const parts: string[] = [];
71	  let length = 0;
72	  let previousBlock: Element | null = null;
73	  const blockTags = new Set([
74	    "ADDRESS",
75	    "ARTICLE",
76	    "ASIDE",
77	    "BLOCKQUOTE",
78	    "DIV",
79	    "FIGCAPTION",
80	    "H1",
81	    "H2",
82	    "H3",
83	    "H4",
84	    "H5",
85	    "H6",
86	    "LI",
87	    "P",
88	    "PRE",
89	    "SECTION",
90	  ]);
91	  const nearestBlock = (textNode: Text): Element => {
92	    let element: Element | null = textNode.parentElement;
93	    while (element && element !== root) {
94	      if (blockTags.has(element.tagName)) return element;
95	      element = element.parentElement;
96	    }
97	    return root;
98	  };
99	  const walker = document.createTreeWalker(
100	    root,
101	    NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT,
102	    {
103	      acceptNode(node) {
104	        const parent = node.parentElement;
105	        if (
106	          !parent ||
107	          parent.closest(
108	            'button, input, select, textarea, script, style, [aria-hidden="true"], [data-speech-ignore]',
109	          )
110	        ) {
111	          return NodeFilter.FILTER_REJECT;
112	        }
113	        if (node instanceof Element)
114	          return node.tagName === "BR"
115	            ? NodeFilter.FILTER_ACCEPT
116	            : NodeFilter.FILTER_SKIP;
117	        if (
118	          !(node as Text).data.trim() &&
119	          ((parent === root && root.children.length) ||
120	            ["UL", "OL", "TABLE", "THEAD", "TBODY", "TR"].includes(
121	              parent.tagName,
122	            ))
123	        ) {
124	          return NodeFilter.FILTER_REJECT;
125	        }
126	        return node.textContent?.length
