133	  let node = walker.nextNode();
134	  while (node) {
135	    if (node instanceof Element) {
136	      parts.push("\n");
137	      length += 1;
138	      node = walker.nextNode();
139	      continue;
140	    }
141	    const textNode = node as Text;
142	    const value = textNode.data;
143	    const block = nearestBlock(textNode);
144	    if (
145	      previousBlock &&
146	      block !== previousBlock &&
147	      !block.contains(previousBlock) &&
148	      !previousBlock.contains(block)
149	    ) {
150	      parts.push("\n\n");
151	      length += 2;
152	    }
153	    slices.push({ node: textNode, start: length, end: length + value.length });
154	    parts.push(value);
155	    length += value.length;
156	    previousBlock = block;
157	    node = walker.nextNode();
158	  }
159	
160	  const text = parts.join("");
161	  const sourceText = currentSpeechText();
162	  const sourceOffset = currentSpeechSourceOffset();
