165	        sourceOffset:
166	          root.dataset.speechSource === "plain" ? sourceOffset : null,
167	        markdown: root.dataset.speechSource !== "plain",
168	      })
169	    : null;
170	  const spokenStart = sourceMap?.renderedStart ?? 0;
171	  const spokenEnd = sourceMap?.renderedEnd ?? text.length;
172	  const timeline = buildSpeechTimeline(text);
173	  return {
174	    root,
175	    text,
176	    slices,
177	    timeline,
178	    sourceMap,
179	    sourceText,
180	    sourceOffset,
181	    spokenStart,
182	    spokenEnd,
183	  };
184	}
