210	function caretOffsetFromPoint(
211	  map: SpeechTextMap,
212	  x: number,
213	  y: number,
214	): number | null {
215	  const documentWithCaret = document as Document & {
216	    caretPositionFromPoint?: (
217	      clientX: number,
218	      clientY: number,
219	    ) => { offsetNode: Node; offset: number } | null;
220	    caretRangeFromPoint?: (clientX: number, clientY: number) => Range | null;
221	  };
222	  const position = documentWithCaret.caretPositionFromPoint?.(x, y);
223	  const fallback = position
224	    ? null
225	    : documentWithCaret.caretRangeFromPoint?.(x, y);
226	  const node = position?.offsetNode ?? fallback?.startContainer;
227	  const offset = position?.offset ?? fallback?.startOffset;
228	  if (
229	    !(node instanceof Text) ||
230	    offset === undefined ||
231	    !map.root.contains(node)
232	  ) {
