import type { AppError } from "../../types/application-errors";

export interface SpeechErrorView {
  title: string;
  message: string;
  retry: boolean;
  retryAfterSeconds?: number;
  recovery?: { label: string; href: string };
  /** Hint to switch voice or provider when the failure is provider-side. */
  suggestVoiceChange: boolean;
}

const TITLES: Partial<Record<AppError["code"], string>> = {
  AUTHENTICATION_REQUIRED: "Sign in to read aloud",
  AUTHENTICATION_FAILED: "Sign-in could not be verified",
  PERMISSION_DENIED: "Read aloud isn't available on this plan",
  RATE_LIMITED: "The voice needs a moment",
  TIMEOUT: "The voice took too long",
  NETWORK_UNAVAILABLE: "Connection interrupted",
  CONFIGURATION_ERROR: "Voice setup needs attention",
  PROVIDER_ERROR: "The voice could not be prepared",
  MALFORMED_RESPONSE: "The audio could not be read",
};

/** Maps a structured error onto honest, actionable player copy. */
export function describeSpeechError(error: AppError | null): SpeechErrorView {
  if (!error) {
    return {
      title: "Read aloud stopped",
      message: "Narration failed.",
      retry: true,
      suggestVoiceChange: false,
    };
  }
  let recovery: SpeechErrorView["recovery"];
  switch (error.recovery.action) {
    case "sign-in":
      recovery = { label: "Sign in", href: "/editor?auth=1" };
      break;
    case "check-configuration":
    case "choose-provider":
      recovery = { label: "Open voice settings", href: "/settings/" };
      break;
    case "download-required":
      recovery = { label: "Open settings to download", href: "/settings/" };
      break;
    default:
      break;
  }
  return {
    title: TITLES[error.code] ?? "Read aloud stopped",
    message: error.message.trim() || "Narration failed.",
    retry: error.recovery.canRetry,
    retryAfterSeconds:
      error.recovery.retryAfterMs === undefined
        ? undefined
        : Math.max(1, Math.ceil(error.recovery.retryAfterMs / 1000)),
    recovery,
    suggestVoiceChange:
      error.code === "PROVIDER_ERROR" || error.code === "MALFORMED_RESPONSE",
  };
}
EOF
cat > speech-error-model.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import type { AppError } from "../../types/application-errors";
import { describeSpeechError } from "./speech-error-model";

const base: AppError = {
  code: "PROVIDER_ERROR",
  message: "The selected provider could not complete the request.",
  referenceId: "err_1",
  source: "provider",
  recovery: { action: "retry", canRetry: true },
};

describe("describeSpeechError", () => {
  test("keeps the full message and offers retry only when retryable", () => {
    const v = describeSpeechError(base);
    expect(v.message).toBe(base.message);
    expect(v.retry).toBe(true);
    expect(v.suggestVoiceChange).toBe(true);
    const none = describeSpeechError({
      ...base,
      recovery: { action: "none", canRetry: false },
    });
    expect(none.retry).toBe(false);
  });

  test("routes sign-in and settings recoveries", () => {
    expect(
      describeSpeechError({
        ...base,
        code: "AUTHENTICATION_REQUIRED",
        recovery: { action: "sign-in", canRetry: false },
      }).recovery?.href,
    ).toBe("/editor?auth=1");
    expect(
      describeSpeechError({
        ...base,
        code: "CONFIGURATION_ERROR",
        recovery: { action: "check-configuration", canRetry: false },
      }).recovery?.href,
    ).toBe("/settings/");
  });

  test("rounds retry-after up and handles a missing error", () => {
    expect(
      describeSpeechError({
        ...base,
        recovery: { action: "retry-later", canRetry: true, retryAfterMs: 1200 },
      }).retryAfterSeconds,
    ).toBe(2);
    expect(describeSpeechError(null).message).toBe("Narration failed.");
  });
});
EOF
cat > speech-error-panel.tsx <<'EOF'
import { component$, useStore, type PropFunction, type Signal } from "@qwik.dev/core";
import { Link } from "@qwik.dev/router";
import type { AppError } from "../../types/application-errors";
import { describeSpeechError } from "./speech-error-model";

interface SpeechErrorPanelProps {
  error: AppError | null;
  label: string;
  queueIndex: number;
  queueLength: number;
  canGoNext: boolean;
  onRetry$: PropFunction<() => void>;
  onNext$: PropFunction<() => void>;
  onClose$: PropFunction<() => void>;
}

/** Full-width, readable failure state for the global narration player. */
export const SpeechErrorPanel = component$((props: SpeechErrorPanelProps) => {
  const view = describeSpeechError(props.error);
  const local = useStore({ copied: false });
  const ref = props.error?.referenceId;

  return (
    <div
      class="p-3"
      role="alert"
      aria-live="assertive"
      data-speech-error={props.error?.code ?? "UNKNOWN"}
    >
      <div class="flex items-start gap-3">
        <span
          class="mt-0.5 text-base leading-none text-[var(--color-vermilion)]"
          style={{ fontFamily: "var(--font-display)" }}
          aria-hidden="true"
        >
          !
        </span>
        <div class="min-w-0 flex-1">
          <p
            class="text-sm font-semibold text-[var(--color-ink)]"
            style={{ fontFamily: "var(--font-display)" }}
          >
            {view.title}
          </p>
          <p
            class="mt-0.5 text-[0.65rem] text-[var(--color-ink-muted)]"
            style={{ fontFamily: "var(--font-typewriter)" }}
          >
            {props.label || "Read aloud"}
            {props.queueLength > 1 &&
              ` · ${props.queueIndex + 1} of ${props.queueLength}`}
          </p>
          <p
            class="mt-1.5 text-[0.8rem] leading-relaxed text-[var(--color-ink-light)]"
            style={{ fontFamily: "var(--font-serif)" }}
          >
            {view.message}
            {view.suggestVoiceChange && " Trying another voice may help."}
          </p>
          {view.retryAfterSeconds !== undefined && (
            <p
              class="mt-1 text-[0.65rem] text-[var(--color-ink-muted)]"
              style={{ fontFamily: "var(--font-typewriter)" }}
            >
              Try again in about {view.retryAfterSeconds} seconds.
            </p>
          )}
          <div class="mt-3 flex flex-wrap items-center gap-2">
            {view.retry && (
              <button
                type="button"
                class="btn-press text-xs"
                onClick$={props.onRetry$}
              >
                Try again
              </button>
            )}
            {view.recovery && (
              <Link class="btn-paper text-xs" href={view.recovery.href}>
                {view.recovery.label}
              </Link>
            )}
            {props.canGoNext && (
              <button
                type="button"
                class="btn-paper text-xs"
                onClick$={props.onNext$}
              >
                Skip to next
              </button>
            )}
          </div>
          {ref && (
            <p
              class="mt-2 flex flex-wrap items-center gap-2 text-[0.6rem] tracking-[0.08em] text-[var(--color-ink-muted)]"
              style={{ fontFamily: "var(--font-typewriter)" }}
            >
              <span class="break-all">Reference {ref}</span>
              <button
                type="button"
                class="focus-ring underline"
                onClick$={async () => {
                  try {
                    await navigator.clipboard.writeText(ref);
                    local.copied = true;
                  } catch {
                    local.copied = false;
                  }
                }}
                aria-label="Copy error reference"
              >
                {local.copied ? "Copied" : "Copy"}
              </button>
            </p>
          )}
        </div>
        <button
          type="button"
          class="tool-btn shrink-0"
          aria-label="Stop narration and close player"
          title="Close"
          onClick$={props.onClose$}
        >
          ×
        </button>
      </div>
    </div>
  );
});

export type { Signal };
EOF
